// loopbackOnly tells whether a subcommand sends the admin credentials and its
// images through the loopback and nowhere else.
func loopbackOnly(name string) bool { return name == "restore-upstream" || name == "reset" }

// isLiteralLoopback tells whether host is a loopback address, not a name:
// the library refuses "localhost" (requireLoopbackBase), as a name resolves
// through the configuration of the host.
func isLiteralLoopback(host string) bool {
	addr, ok := hostAddress(host)
	return ok && addr.Unmap().IsLoopback()
}

// isLoopbackHost tells whether host stays on this machine.
func isLoopbackHost(host string) bool {
	if strings.EqualFold(host, "localhost") {
		return true
	}
	addr, ok := hostAddress(host)
	return ok && addr.Unmap().IsLoopback()
